      } else if (!_accepted && d.dy.abs() > kTouchSlop) {
        resolve(GestureDisposition.rejected); return;
      }
      if (_accepted) onScrub?.call(e.position);
    } else if (e is PointerUpEvent || e is PointerCancelEvent) {
      onEnd?.call(); stopTrackingPointer(e.pointer);
    }
  }
  @override
  void rejectGesture(int pointer) => stopTrackingPointer(pointer);
  @override
  void didStopTrackingLastPointer(int pointer) {}
  @override
  String get debugDescription => 'chartScrub';
}
